#!/usr/bin/env python3
"""Offline DNS model-based regression workbench."""

import array
import ipaddress
import json
import math
import re
import sys


class InvalidInput(Exception):
    pass


_ID_RE = re.compile(r"[A-Za-z0-9_-]{1,32}")
_LABEL_RE = re.compile(r"[A-Za-z0-9_-]{1,63}")
_TYPES = {"A", "AAAA", "TXT", "CNAME"}
_RCODES = {"NOERROR", "NXDOMAIN", "SERVFAIL", "REFUSED"}
_MAX_INPUT = 8 * 1024 * 1024


def _object_without_duplicate_keys(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise InvalidInput()
        result[key] = value
    return result


def _finite_float(text):
    value = float(text)
    if not math.isfinite(value):
        raise InvalidInput()
    return value


def _reject_constant(_text):
    raise InvalidInput()


def _exact_object(value, fields):
    if type(value) is not dict or set(value) != set(fields):
        raise InvalidInput()


def _identifier(value):
    if type(value) is not str or _ID_RE.fullmatch(value) is None:
        raise InvalidInput()
    return value


def _name(value):
    """Validate and canonicalize an absolute domain name."""
    if type(value) is not str or not value.isascii():
        raise InvalidInput()
    if value == ".":
        return "."
    if not value.endswith("."):
        raise InvalidInput()
    labels = value[:-1].split(".")
    wire_length = 1
    for label in labels:
        if label == "*":
            length = 1
        elif _LABEL_RE.fullmatch(label) is not None:
            length = len(label)
        else:
            raise InvalidInput()
        wire_length += length + 1
    if wire_length > 255:
        raise InvalidInput()
    return value.lower()


def _labels(name):
    if name == ".":
        return ()
    return tuple(name[:-1].split("."))


def _from_labels(labels):
    if not labels:
        return "."
    return ".".join(labels) + "."


def _record(value):
    """Validate one record and return its canonical (owner, type, data)."""
    _exact_object(value, ("owner", "type", "data"))
    owner = _name(value["owner"])
    rtype = value["type"]
    data = value["data"]
    if type(rtype) is not str or rtype not in _TYPES or type(data) is not str:
        raise InvalidInput()

    if rtype == "A":
        octets = data.split(".")
        if len(octets) != 4:
            raise InvalidInput()
        for octet in octets:
            if not octet or not octet.isascii() or not octet.isdigit():
                raise InvalidInput()
            if len(octet) > 1 and octet[0] == "0":
                raise InvalidInput()
            if int(octet) > 255:
                raise InvalidInput()
        canonical_data = data
    elif rtype == "AAAA":
        if "%" in data:
            raise InvalidInput()
        try:
            canonical_data = ipaddress.IPv6Address(data).compressed
        except Exception as exc:
            raise InvalidInput() from exc
    elif rtype == "TXT":
        if len(data) > 256 or not data.isascii():
            raise InvalidInput()
        if any(ord(char) < 0x20 or ord(char) > 0x7E for char in data):
            raise InvalidInput()
        canonical_data = data
    else:  # CNAME
        canonical_data = _name(data)

    return owner, rtype, canonical_data


def _check_container_depth_and_numbers(document):
    # Iterative traversal avoids depending on the Python recursion limit.
    stack = [(document, 1)]
    while stack:
        value, depth = stack.pop()
        if type(value) is dict:
            if depth > 32:
                raise InvalidInput()
            stack.extend((item, depth + 1) for item in value.values())
        elif type(value) is list:
            if depth > 32:
                raise InvalidInput()
            stack.extend((item, depth + 1) for item in value)
        elif type(value) is float and not math.isfinite(value):
            raise InvalidInput()


def _parse_zones(zones):
    if type(zones) is not list or len(zones) > 16:
        raise InvalidInput()

    parsed = []
    origins = set()
    total_entries = 0
    for zone in zones:
        _exact_object(zone, ("origin", "records"))
        origin = _name(zone["origin"])
        if origin in origins:
            raise InvalidInput()
        origins.add(origin)
        entries = zone["records"]
        if type(entries) is not list:
            raise InvalidInput()
        total_entries += len(entries)
        if total_entries > 1024:
            raise InvalidInput()

        origin_labels = _labels(origin)
        collapsed = set()
        for entry in entries:
            record = _record(entry)
            owner_labels = _labels(record[0])
            n = len(origin_labels)
            if len(owner_labels) < n or (n and owner_labels[-n:] != origin_labels):
                raise InvalidInput()
            collapsed.add(record)

        by_owner = {}
        rrset_counts = {}
        for owner, rtype, data in collapsed:
            by_owner.setdefault(owner, {}).setdefault(rtype, []).append(data)
            key = (owner, rtype)
            rrset_counts[key] = rrset_counts.get(key, 0) + 1
            if rrset_counts[key] > 64:
                raise InvalidInput()

        records = {}
        for owner, types in by_owner.items():
            if "CNAME" in types:
                if len(types) != 1 or len(types["CNAME"]) != 1 or owner == origin:
                    raise InvalidInput()
            records[owner] = {
                rtype: tuple(sorted(values)) for rtype, values in types.items()
            }

        existing = {origin}
        for owner in by_owner:
            current = _labels(owner)
            while True:
                existing.add(_from_labels(current))
                if current == origin_labels:
                    break
                current = current[1:]

        parsed.append({
            "origin": origin,
            "origin_labels": origin_labels,
            "records": records,
            "existing": existing,
        })

    parsed.sort(key=lambda zone: len(zone["origin_labels"]), reverse=True)
    return parsed


def _parse_profiles(profiles):
    if type(profiles) is not list or not 1 <= len(profiles) <= 8:
        raise InvalidInput()
    result = []
    ids = set()
    for profile in profiles:
        _exact_object(profile, ("id", "max_aliases", "cname", "wildcard"))
        pid = _identifier(profile["id"])
        if pid in ids:
            raise InvalidInput()
        ids.add(pid)
        maximum = profile["max_aliases"]
        if type(maximum) is not int or not 0 <= maximum <= 64:
            raise InvalidInput()
        if profile["cname"] not in ("follow", "stop"):
            raise InvalidInput()
        if profile["wildcard"] not in ("rfc", "off", "one-label"):
            raise InvalidInput()
        result.append({
            "id": pid,
            "max_aliases": maximum,
            "cname": profile["cname"],
            "wildcard": profile["wildcard"],
        })
    result.sort(key=lambda profile: profile["id"])
    return result


def _parse_queries(queries):
    if type(queries) is not list or len(queries) > 20:
        raise InvalidInput()
    result = []
    ids = set()
    for query in queries:
        _exact_object(query, ("id", "name", "type", "cost"))
        qid = _identifier(query["id"])
        if qid in ids:
            raise InvalidInput()
        ids.add(qid)
        name = _name(query["name"])
        qtype = query["type"]
        if type(qtype) is not str or qtype not in _TYPES:
            raise InvalidInput()
        cost = query["cost"]
        if type(cost) is not int or not 1 <= cost <= 1000:
            raise InvalidInput()
        result.append({"id": qid, "name": name, "type": qtype, "cost": cost})
    result.sort(key=lambda query: query["id"])
    return result


def _parse_observations(observations, query_ids, profile_ids):
    if type(observations) is not list or len(observations) > 64:
        raise InvalidInput()
    result = []
    ids = set()
    for observation in observations:
        _exact_object(observation, ("id", "query", "profile", "result"))
        oid = _identifier(observation["id"])
        if oid in ids:
            raise InvalidInput()
        ids.add(oid)
        qid = observation["query"]
        pid = observation["profile"]
        if type(qid) is not str or type(pid) is not str:
            raise InvalidInput()
        if qid not in query_ids or pid not in profile_ids:
            raise InvalidInput()
        observed = observation["result"]
        if type(observed) is not dict or "status" not in observed:
            raise InvalidInput()
        if observed["status"] == "timeout":
            _exact_object(observed, ("status",))
            result.append({"id": oid, "query": qid, "profile": pid,
                           "timeout": True})
        elif observed["status"] == "response":
            _exact_object(observed, ("status", "rcode", "answer"))
            rcode = observed["rcode"]
            if type(rcode) is not str or rcode not in _RCODES:
                raise InvalidInput()
            answer = observed["answer"]
            if type(answer) is not list or len(answer) > 128:
                raise InvalidInput()
            records = {_record(entry) for entry in answer}
            result.append({"id": oid, "query": qid, "profile": pid,
                           "timeout": False, "rcode": rcode,
                           "answer": frozenset(records)})
        else:
            raise InvalidInput()
    result.sort(key=lambda observation: observation["id"])
    return result


def _matching_zone(zones, current_labels):
    for zone in zones:  # Already sorted by decreasing origin label count.
        origin = zone["origin_labels"]
        n = len(origin)
        if n == 0 or (len(current_labels) >= n and current_labels[-n:] == origin):
            return zone
    return None


def _resolve(query, profile, zones):
    current = query["name"]
    qtype = query["type"]
    seen = set()
    followed = 0
    answer = []
    trace = []

    while True:
        trace.append(current)
        if current in seen:
            termination = "LOOP"
            rcode = "SERVFAIL"
            break
        seen.add(current)

        current_labels = _labels(current)
        zone = _matching_zone(zones, current_labels)
        if zone is None:
            if followed == 0:
                rcode, termination = "REFUSED", "OUTSIDE"
            else:
                rcode, termination = "NOERROR", "EXTERNAL"
            break

        source = None
        if current in zone["existing"]:
            source = current
        elif profile["wildcard"] != "off":
            encloser_labels = current_labels[1:]
            encloser = _from_labels(encloser_labels)
            while encloser not in zone["existing"]:
                encloser_labels = encloser_labels[1:]
                encloser = _from_labels(encloser_labels)
            wildcard_labels = ("*",) + encloser_labels
            candidate = _from_labels(wildcard_labels)
            one_label = len(current_labels) == len(encloser_labels) + 1
            if ((profile["wildcard"] == "rfc" or one_label)
                    and candidate in zone["existing"]):
                source = candidate

        if source is None:
            rcode, termination = "NXDOMAIN", "NXDOMAIN"
            break

        source_records = zone["records"].get(source, {})
        cname_targets = source_records.get("CNAME")

        if qtype == "CNAME":
            if cname_targets is not None:
                for target in cname_targets:
                    answer.append((current, "CNAME", target))
                rcode, termination = "NOERROR", "ANSWER"
            else:
                rcode, termination = "NOERROR", "NODATA"
            break

        if cname_targets is not None:
            if profile["cname"] == "stop":
                for target in cname_targets:
                    answer.append((current, "CNAME", target))
                rcode, termination = "NOERROR", "CNAME_STOP"
                break
            if followed == profile["max_aliases"]:
                rcode, termination = "SERVFAIL", "LIMIT"
                break
            # Zone validation guarantees exactly one CNAME target.
            target = cname_targets[0]
            answer.append((current, "CNAME", target))
            followed += 1
            current = target
            continue

        requested = source_records.get(qtype)
        if requested is not None:
            for data in requested:
                answer.append((current, qtype, data))
            rcode, termination = "NOERROR", "ANSWER"
        else:
            rcode, termination = "NOERROR", "NODATA"
        break

    output_answer = [
        {"owner": owner, "type": rtype, "data": data}
        for owner, rtype, data in answer
    ]
    run = {
        "query": query["id"],
        "profile": profile["id"],
        "rcode": rcode,
        "termination": termination,
        "final_name": current,
        "answer": output_answer,
        "trace": trace,
    }
    return run, (rcode, frozenset(answer))


def _diagnostic(queries, profiles, signatures):
    profile_ids = [profile["id"] for profile in profiles]
    query_ids = [query["id"] for query in queries]

    class_by_vector = {}
    for pid in profile_ids:
        vector = tuple(signatures[qid, pid] for qid in query_ids)
        class_by_vector.setdefault(vector, []).append(pid)
    classes = sorted(class_by_vector.values())
    class_number = {}
    for number, members in enumerate(classes):
        for pid in members:
            class_number[pid] = number

    diagnostic = {"equivalence": classes, "basis": [], "cost": 0, "count": 0}
    if len(classes) <= 1:
        return diagnostic

    pairs = []
    for i, first in enumerate(profile_ids):
        for second in profile_ids[i + 1:]:
            if class_number[first] != class_number[second]:
                pairs.append((first, second))
    target = (1 << len(pairs)) - 1

    # Zero-coverage tests are useless.  For identical coverage, only the
    # cheapest test can occur in an optimum (all query costs are positive).
    by_coverage = {}
    for query in queries:
        qid = query["id"]
        coverage = 0
        for bit, (first, second) in enumerate(pairs):
            if signatures[qid, first] != signatures[qid, second]:
                coverage |= 1 << bit
        if coverage == 0:
            continue
        old = by_coverage.get(coverage)
        if old is None or query["cost"] < old["cost"]:
            by_coverage[coverage] = query

    candidates = sorted(by_coverage.values(), key=lambda query: query["id"])
    coverages = list(by_coverage)
    # Keep coverage and query arrays aligned after sorting by query ID.
    coverages = []
    for query in candidates:
        qid = query["id"]
        coverage = 0
        for bit, (first, second) in enumerate(pairs):
            if signatures[qid, first] != signatures[qid, second]:
                coverage |= 1 << bit
        coverages.append(coverage)

    n = len(candidates)
    subset_count = 1 << n
    subset_coverage = array.array("I", [0]) * subset_count
    subset_cost = array.array("I", [0]) * subset_count
    query_costs = [query["cost"] for query in candidates]

    best_cost = None
    best_count = 0
    best_mask = 0
    for mask in range(1, subset_count):
        low_bit = mask & -mask
        index = low_bit.bit_length() - 1
        previous = mask ^ low_bit
        coverage = subset_coverage[previous] | coverages[index]
        cost = subset_cost[previous] + query_costs[index]
        subset_coverage[mask] = coverage
        subset_cost[mask] = cost
        if coverage == target:
            count = mask.bit_count()
            if (best_cost is None or cost < best_cost
                    or (cost == best_cost and count < best_count)):
                best_cost = cost
                best_count = count
                best_mask = mask

    # The full candidate set covers every required pair, so an optimum exists.
    basis = [candidates[i]["id"] for i in range(n) if best_mask & (1 << i)]
    diagnostic["basis"] = sorted(basis)
    diagnostic["cost"] = best_cost
    diagnostic["count"] = best_count
    return diagnostic


def analyze(document):
    _exact_object(document, ("zones", "profiles", "queries", "observations"))
    for key in ("zones", "profiles", "queries", "observations"):
        if type(document[key]) is not list:
            raise InvalidInput()

    zones = _parse_zones(document["zones"])
    profiles = _parse_profiles(document["profiles"])
    queries = _parse_queries(document["queries"])
    observations = _parse_observations(
        document["observations"],
        {query["id"] for query in queries},
        {profile["id"] for profile in profiles},
    )

    runs = []
    signatures = {}
    run_by_pair = {}
    for query in queries:
        for profile in profiles:
            run, signature = _resolve(query, profile, zones)
            runs.append(run)
            signatures[query["id"], profile["id"]] = signature
            run_by_pair[query["id"], profile["id"]] = signature

    audits = []
    for observation in observations:
        if observation["timeout"]:
            verdict = "unobserved"
            different = []
        else:
            signature = run_by_pair[observation["query"], observation["profile"]]
            different = []
            if observation["rcode"] != signature[0]:
                different.append("rcode")
            if observation["answer"] != signature[1]:
                different.append("answer")
            verdict = "divergence" if different else "match"
        audits.append({"id": observation["id"], "verdict": verdict,
                       "different": different})

    return {
        "runs": runs,
        "audits": audits,
        "diagnostic": _diagnostic(queries, profiles, signatures),
    }


def main():
    try:
        raw = sys.stdin.buffer.read(_MAX_INPUT + 1)
        if len(raw) > _MAX_INPUT:
            raise InvalidInput()
        text = raw.decode("utf-8")
        document = json.loads(
            text,
            object_pairs_hook=_object_without_duplicate_keys,
            parse_float=_finite_float,
            parse_constant=_reject_constant,
        )
        _check_container_depth_and_numbers(document)
        result = analyze(document)
        output = json.dumps(result, separators=(",", ":"), ensure_ascii=True)
    except Exception:
        output = '{"error":"invalid-input"}'
    sys.stdout.write(output + "\n")


if __name__ == "__main__":
    main()
